// Compares the editor's JS port of the fork's 514c:8850 (12-key/4-knob) protocol against packets produced by the
// fork's own Rust code (fork/fork_oracle.txt, generated by the cfg(test) harness in fork/src).
const fs=require('fs'), path=require('path');
const htmlPath=process.argv[2]||'/home/claude/ch57x-config-editor.html';
const html=fs.readFileSync(htmlPath,'utf8');
const core=html.match(/<script id="core">([\s\S]*?)<\/script>/)[1];
const api=new Function(core+';return {parseActionToMacro,bindPackets,makeReport,planUpload,resolveFamily,familyWarnings,keyIdFor,normalizeState};')();
const FAM='884x-514c';
const KEYS={b0:0,b5:5,b11:11,b14:14,b15:15,k0ccw:[0,'ccw'],k0press:[0,'press'],k1cw:[1,'cw'],k2press:[2,'press'],
  k3ccw:[3,'ccw'],k3press:[3,'press'],k3cw:[3,'cw'],k4press:[4,'press']};
// fork syntax -> editor syntax (the editor keeps the upstream YAML syntax)
function toEditor(a){
  let s=a, m;
  if((m=s.match(/^delay\[(\d+)\],(.*)$/))) s='{delay('+m[1]+')}'+m[2];
  s=s.replace(/mousemove\[(-?\d+),(-?\d+)\]/g,'move($1,$2)');
  return s;
}
const hexOf=arr=>{ const b=Array.from(arr); while(b.length&&b[b.length-1]===0) b.pop(); return b.map(x=>x.toString(16).padStart(2,'0')).join(' '); };
const lines=fs.readFileSync(path.join(__dirname,'../fork/fork_oracle.txt'),'utf8').split('\n').filter(l=>l.startsWith('FORK|')).map(l=>l.split('|'));
let ok=0, bad=0, errOk=0; const dev=new Set(); const diffs=[];
for(const [_,action,layer,key,status,...rest] of lines){
  let mine,err;
  try{
    const macro=api.parseActionToMacro(toEditor(action));
    mine=api.bindPackets(FAM,+layer,KEYS[key],macro).map(p=>hexOf(api.makeReport(p))).join(' ; ');
  }catch(e){ err=e.message; }
  if(status==='ERR'){ if(err) errOk++; else { bad++; diffs.push([action,layer,key,'rust ERR ('+rest.join('|')+') but mine OK: '+mine]); } continue; }
  const rust=rest[0].split(' ; ').map(ch=>hexOf(ch.trim().split(' ').slice(1).map(h=>parseInt(h,16)))).join(' ; ');   // drop report id 03
  if(err && /out of range -127\.\.127/.test(err) && /-128/.test(action)){ ok++; dev.add(action); }   // intentional: editor limits movement to -127..127
  else if(err){ bad++; diffs.push([action,layer,key,'mine ERR ('+err+') but rust OK']); }
  else if(mine===rust) ok++; else { bad++; diffs.push([action,layer,key,'\n   mine: '+mine+'\n   rust: '+rust]); }
}
console.log('packet comparisons: identical='+ok+'  both-reject='+errOk+'  differing='+bad+'  (of '+lines.length+')');
if(dev.size) console.log('intentional -128 rejections:',[...dev].join(' , '));
diffs.slice(0,15).forEach(d=>console.log('DIFF',d.join(' ')));
let fails=bad;

// ---- orientation + 4 knobs: independent port of reorient_grid / reorient_row / Key::to_key_id from the fork ----
function reorientGrid(o,rows,cols,data){
  const tr={normal:(r,c)=>[r,c],upsidedown:(r,c)=>[rows-r-1,cols-c-1],clockwise:(r,c)=>[c,rows-r-1],counterclockwise:(r,c)=>[cols-c-1,r]}[o];
  return Array.from({length:rows*cols},(_,i)=>{const [r,c]=tr(Math.floor(i/cols),i%cols); return data[r][c];});
}
const reorientRow=(o,d)=> (o==='upsidedown'||o==='clockwise') ? [...d].reverse() : [...d];
const forkKid={button:n=>n+1, knob:(n,a)=> n===3 ? 13+a : 16+3*n+a};
let ob=0, checked=0;
for(const o of ['normal','upsidedown','clockwise','counterclockwise']) for(const [rows,cols] of [[3,4],[4,3]]){
  const vert=o==='clockwise'||o==='counterclockwise', R=vert?cols:rows, C=vert?rows:cols;
  let n=10; const grid=Array.from({length:R},()=>Array.from({length:C},()=>'<'+(n++)+'>'));
  const knobsV=Array.from({length:4},()=>({ccw:'<'+(n++)+'>',press:'<'+(n++)+'>',cw:'<'+(n++)+'>'}));
  const st=api.normalizeState({orientation:o,rows,columns:cols,knobs:4,layers:[{buttons:grid,knobs:knobsV}]});
  const plan=api.planUpload(st,FAM,0);
  if(plan.errors.length){ ob++; console.log('plan errors',o,rows,cols,plan.errors); continue; }
  const got={};   // kid -> action text
  plan.packets.forEach(p=>{ if(!p.desc) return; const m=p.desc.match(/<- (.*)$/); got[p.bytes[1]]=m[1]; });
  const flatB=reorientGrid(o,rows,cols,grid), flatK=reorientRow(o,knobsV);
  flatB.forEach((v,i)=>{ checked++; if(got[forkKid.button(i)]!==v){ ob++; console.log('ORIENT button',o,rows+'x'+cols,'phys',i,'want',v,'got',got[forkKid.button(i)]); } });
  flatK.forEach((k,j)=>['ccw','press','cw'].forEach((a,ai)=>{ checked++; const kid=forkKid.knob(j,ai); if(got[kid]!==k[a]){ ob++; console.log('ORIENT knob',o,'phys',j,a,'want',k[a],'got',got[kid]); } }));
}
console.log('orientation / 4-knob id checks: '+checked+', mismatches: '+ob);
fails+=ob;

// ---- family resolution for the shared 514c:8850 id ----
let rf=0;
const st=(r,c)=>({rows:r,columns:c});
const exp=[[0x514c,0x8850,st(3,4),'884x-514c'],[0x514c,0x8850,st(4,4),'8850'],[0x514c,0x8850,st(2,6),'884x-514c'],
  [0x1189,0x8840,st(3,4),'884x'],[0x1189,0x8890,st(3,4),'8890'],[0x1189,0x8842,st(4,4),'884x'],[0x1234,0x8850,st(3,4),null]];
for(const [v,p,s,want] of exp){ const got=api.resolveFamily(v,p,s); if(got!==want){ rf++; console.log('RESOLVE',v.toString(16),p.toString(16),s.rows*s.columns,'want',want,'got',got); } }
console.log('family resolution mismatches:',rf); fails+=rf;

// ---- warnings ----
let wf=0;
const w1=api.familyWarnings(FAM,api.parseActionToMacro('ctrl-click')), w2=api.familyWarnings(FAM,api.parseActionToMacro('click')),
  w3=api.familyWarnings('884x',api.parseActionToMacro('ctrl-click')), w4=api.familyWarnings(FAM,api.parseActionToMacro('ctrl-wheelup'));
if(w1.length!==1||w2.length||w3.length||w4.length){ wf++; console.log('warnings wrong',w1,w2,w3,w4); }
const st2=api.normalizeState({orientation:'normal',rows:3,columns:4,knobs:1,layers:[{buttons:[['ctrl-click','','',''],['','','',''],['','','','']],knobs:[{ccw:'',press:'',cw:''}]}]});
const pl=api.planUpload(st2,FAM,0); if(pl.warnings.length!==1||pl.errors.length){ wf++; console.log('plan warnings wrong',pl.warnings,pl.errors); }
// unsupported in this variant -> errors, not silent
for(const a of ['alt-drag(right,10,0)','wheel(3)','wheel(0)','move(0,0)x']){
  let threw=false; try{ api.bindPackets(FAM,0,0,api.parseActionToMacro(a)); }catch(e){ threw=true; }
  const expectThrow = !a.startsWith('move(0,0)x');
  if(expectThrow && !threw){ wf++; console.log('should reject',a); }
}
// 4x4 pad path still uses the upstream protocol, unchanged
const p4=api.bindPackets('8850',0,0,api.parseActionToMacro('ctrl-a')).map(p=>hexOf(api.makeReport(p))).join(' ; ');
console.log('4x4 ctrl-a b0 (unchanged):',p4);
console.log('warning/unsupported checks failed:',wf); fails+=wf;
console.log(fails?'FAIL':'ALL OK');
process.exit(fails?1:0);
